const {test}=require('node:test');
const assert=require('node:assert/strict');
const C=require('../src/core.js');
test('nascimento e nível 99 respeitam o orçamento aprovado',()=>{const p=C.fresh();assert.equal(p.unspent,5);assert.equal(p.treePoints,0);assert.equal(p.learned,false);for(let n=1;n<99;n++)C.gainXP(p,C.xpFor(p.level));assert.equal(p.level,99);assert.equal(p.unspent,495);assert.equal(p.treePoints,98);assert.equal(Object.values(p.attrs).reduce((a,b)=>a+b),20);});
test('atributo e talento atualizam vida e poder, sem gastar mais pontos',()=>{const p=C.fresh();assert.equal(C.stats(p).hp,300);C.allocate(p,'vitalidade');assert.equal(C.stats(p).hp,320);assert.equal(p.hp,320);assert.equal(C.buyNode(p,'road_0_1'),false);C.gainXP(p,30);assert.equal(C.buyNode(p,'keystone_0'),false);assert.equal(C.buyNode(p,'road_0_1'),true);assert.equal(C.stats(p).forca,7);assert.equal(C.buyNode(p,'road_0_1'),false);assert.equal(p.treePoints,0);});
test('mitigação, crítico e bloqueio têm a ordem especificada',()=>{assert.equal(C.damage(100,500),50);assert.equal(C.damage(100,500,true),75);assert.equal(C.damage(100,500,true,true),23);assert.equal(C.damage(100,-500),100);});
test('cone acerta à frente e respeita arco, alcance e costas',()=>{assert.equal(C.cone(0,0,0,50,0,64),true);assert.equal(C.cone(0,0,0,-20,0,64),false);assert.equal(C.cone(0,0,0,30,40,64),false);assert.equal(C.cone(0,0,0,80,0,64),false);});
test('ação válida consome mana/recarga no início, cancelamento não devolve',()=>{const s={mp:10,action:null,cooldowns:{frontal:0}},spec={id:'frontal',mana:10,cooldown:5,windup:.25,recovery:.35,angle:0};assert.equal(C.startAction(s,spec),true);assert.equal(s.mp,0);assert.equal(s.cooldowns.frontal,5);s.action=null;assert.equal(C.startAction(s,spec),false);assert.equal(s.mp,0);assert.equal(s.cooldowns.frontal,5);});
test('dash para no terreno e pode percorrer 3 metros',()=>{const end=C.dashEnd(100,100,1,0,x=>x<140);assert.equal(end.x,136);assert.equal(C.dashEnd(100,100,1,0,()=>true).x,196);assert.equal(C.validPosition(C.riverX(800),800,13),false);assert.equal(C.validPosition(C.riverX(1120),1120,13),true);});
test('recompensas são idempotentes e introdução leva ao nível de treino',()=>{const p=C.fresh();assert.equal(C.turnIn(p),true);assert.equal(C.turnIn(p),false);p.flags.stone=true;p.flags.dodged=true;C.turnIn(p);p.flags.broto=3;p.flags.gosma=2;C.gainXP(p,3*20+2*24);C.turnIn(p);p.flags.crystals=[0,1,2];C.gainXP(p,30);C.turnIn(p);assert.equal(p.quest,4);assert.equal(p.level,5);assert.ok(p.gold>=5);assert.equal(C.turnIn(p),false);});
test('equipamento exige posse, nível e atributos válidos',()=>{const p=C.fresh();p.bag.push('lamina');assert.equal(C.equip(p,'lamina'),false);while(p.level<5)C.gainXP(p,C.xpFor(p.level));assert.equal(C.equip(p,'lamina'),false);for(let i=0;i<5;i++)C.allocate(p,'forca');assert.equal(C.equip(p,'lamina'),true);assert.equal(p.equipment.weapon,'lamina');});
test('importação valida orçamentos, itens, árvores e valores não finitos',()=>{const p=C.fresh('<teste>');p.level=2;p.attrs.forca=500;p.unspent=999;delete p.passiveVersion;p.tree=['bastiao','f2','f1','root','fake'];p.treePoints=900;p.bag=['fake','lamina'];p.equipment.weapon='lamina';p.hp=Infinity;p.x=NaN;p.flags.crystals=[0,0,2,99];const v=C.validateSave(p);assert.equal(v.attrs.forca,15);assert.equal(v.unspent,0);assert.deepEqual(v.tree,[]);assert.equal(v.treePoints,1);assert.equal(v.passiveRefunded,1);assert.equal(v.equipment.weapon,'espada');assert.equal(v.hp,C.stats(v).hp);assert.equal(v.x,C.SPAWN.x);assert.deepEqual(v.flags.crystals,[0,2]);assert.throws(()=>C.validateSave({version:44}));});
test('progresso exportado passa por ida e volta sem perder a build',()=>{const p=C.fresh('Ayla');C.gainXP(p,200);C.allocate(p,'forca');C.buyNode(p,'road_0_1');p.flags.crystals=[0,1];p.rewards=[0];p.quest=1;const v=C.validateSave(JSON.parse(JSON.stringify(p)));assert.equal(v.name,'Ayla');assert.equal(v.level,p.level);assert.equal(v.unspent,p.unspent);assert.deepEqual(v.tree,p.tree);assert.deepEqual(v.flags,p.flags);});
